std::random_device rd;
std::mt19937 gen(rd());
const double k_B = 1.380649e-23; // Boltzmann constant

vec3 centerOfMassVelocity(0, 0, 0);
double totalMass = 0.0;

for (std::size_t i = 0; i < velocities.size(); ++i) {
    double mass = masses[i];
    double sigma = std::sqrt(k_B * temperature / mass);
    std::normal_distribution<double> dist(0.0, sigma);

    velocities[i] = vec3(dist(gen), dist(gen), dist(gen));

    centerOfMassVelocity += velocities[i] * mass;
    totalMass += mass;
}

if (totalMass > 0) {
    centerOfMassVelocity /= totalMass;
    for (std::size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] -= centerOfMassVelocity;
    }
}
// END_CODE

